import React, { useContext } from 'react';
import { Link, Navigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { AuthContext } from '../context/AuthContext';
import Console, { Card } from '../workspaces/Console';
import '../workspaces/workspaces.css';

// Where the person goes from here: the console's own tools first, then the products and the desktop app.
const destinations = [
  { title: 'Workspaces', description: 'Projects, people and connected apps.', to: '/workspaces' },
  { title: 'RMS', description: 'Requirements, links and evidence for a project.', to: '/rms', keepBrandName: true },
  { title: 'Stream workspace', description: 'Capture engineering events and explore their history.', to: '/stream/workspace' },
  { title: 'Plotune Nexus', description: 'Connect your tools and AI agents to the test bench.', to: '/docs/nexus/quick-start', hint: 'Set up' },
  { title: 'Plotune Bridge', description: 'Pair a Bridge device and watch its CAN traffic.', to: 'https://bridge.plotune.net', external: true },
  { title: 'Plotune Desktop', description: 'Get the desktop app for your engineering workflows.', to: '/download', hint: 'Download' },
];

const crumbs = [{ label: 'Dashboard' }];

export default function Dashboard() {
  const { token, isLoading } = useContext(AuthContext);
  if (isLoading) return <Console crumbs={crumbs}><main className="cs-main" role="status">Loading your account…</main></Console>;
  if (!token) return <Navigate to="/login" replace />;

  return (
    <Console crumbs={crumbs}>
      <main className="cs-main cs-main--page">
        <Helmet>
          <title>Dashboard · Plotune</title>
          <meta name="robots" content="noindex,nofollow" />
        </Helmet>
        <h1 className="sr-only">Dashboard</h1>
        <Card title={<>Products and tools<small>{destinations.length}</small></>} headingId="dashboard-tools">
          <ul className="cs-list" aria-labelledby="dashboard-tools">
            {destinations.map(({ title, description, to, external, hint, keepBrandName }) => {
              const body = (
                <>
                  <span className="cs-row__main">
                    <strong translate={keepBrandName || title.startsWith('Plotune') ? 'no' : undefined}>{title}</strong>
                    <span>{description}</span>
                  </span>
                  <span className="cs-action" aria-hidden="true">{hint || 'Open'}</span>
                  {external && <span className="sr-only">(opens in a new tab)</span>}
                </>
              );
              // Bridge is a separate site, so it is a plain link rather than a router link.
              return (
                <li key={to}>
                  {external
                    ? <a href={to} target="_blank" rel="noopener noreferrer" className="cs-row cs-row--link">{body}</a>
                    : <Link to={to} className="cs-row cs-row--link">{body}</Link>}
                </li>
              );
            })}
          </ul>
        </Card>
      </main>
    </Console>
  );
}
